export const createVisitorsInsights = async () => {
      const messageList = store.getState().message;
      const browserName = getBrowserName();
      const device = getDeviceType();

      const checkvisitorId = sessionStorage.getItem('visitorId');
      if (checkvisitorId) return;

      let data = {
            domainId: messageList.personalisationAll?.domainId,
            customerId: messageList.customerFormData?.coid,
            dateAndTime: sessionStorage.getItem("sessionUniqueId"),
            location: '',
            browserDetails: browserName,
            deviceType: device,
            ipAddress: messageList?.storeIpAddress,
            language: window.navigator.language,
            entryTime: sessionStorage.getItem("sessionUniqueId"),
      }
      fetch(`${config().REPORTSERVICE_URL}/insert_update_visitor_insight`, {
            method: 'POST',
            headers: {
                  'Content-Type': 'application/json',
            },
            body: JSON.stringify(data),
      })
            .then((res) => {
                  if (!res.ok) {
                        throw new Error('Network response was not ok: ' + res.statusText);
                  }
                  return res.json();
            })
            .then((data) => {
                  if (data?.statusCode === 200) {
                        const visitorId = data?.result[0]?.visitorId;
                        sessionStorage.setItem('visitorId', visitorId);
                  }
            })
            .catch((error) => {
                  console.error('Error inserting/updating visitor insight:', error);
            });
}

