export const removeUserFromQueue = (nodeId) => {
      try {
            const messageList = store.getState().message;
            const nodeDetails = messageList?.nodeData?.filter((list) => list?.id === nodeId);
            const queueId = nodeDetails[0]?.data?.information?.type === 1 ? nodeDetails[0]?.data?.information?.transferTo : 0
            store.dispatch(liveTrackerActions.setTransferQueueId(queueId))
            sessionStorage.setItem('qid', queueId);
      } catch (err) {
            console.log(err)
      }
}


export const changeFallBackQueue = (data) => {
      if (data?.qid) {
            store.dispatch(liveTrackerActions.setTransferQueueId(data?.qid));
            sessionStorage.setItem('qid', data?.qid)
      }
}

export const clearSessionStorage = () => {
      try {
            const liveTracker = store.getState().liveTracker;
            sessionStorage.removeItem('qid')
            sessionStorage.removeItem('status')
            sessionStorage.removeItem('domainId')
            sessionStorage.removeItem('isConnected')
            sessionStorage.removeItem('payment')
            sessionStorage.removeItem('AMOUNT')
            sessionStorage.removeItem('chatUniqIdentifier')
            sessionStorage.removeItem('ChatHistoryId')
            sessionStorage.removeItem('ChatDurationHistoryId')
            sessionStorage.removeItem('iconStatus')
            sessionStorage.removeItem('item')
            sessionStorage.removeItem('agentToAddress')
            sessionStorage.removeItem('visitorId')
            sessionStorage.removeItem('sessionUniqueId')
            localStorage.removeItem('dynamicDomainUrl')
            localStorage.removeItem('WixPayment')
            localStorage.removeItem('transactionId')
            console.log('Entered::::::::::243')
            store.dispatch(messageActions.sessionClosedStatus(false))
            store.dispatch(messageActions.formVisible(true));
            store.dispatch(liveTrackerActions.setIconHideStatus(false));
            const device = isMobileCheck();
            store.dispatch(liveTrackerActions.setSettingStatus(false));
            store.dispatch(liveTrackerActions.setSocketData(null));
            console.log('Entered::::::::::')
            disconnectSocket()
            store.dispatch(messageActions.reset());
            store.dispatch(chatBuilderActions.reset());
            store.dispatch(liveTrackerActions.reset());
            if (device) {
                  store.dispatch(liveTrackerActions.setMobileIconStatus(false))
            };

            store.dispatch(liveTrackerActions.setReloadSettings())
      } catch (err) {
            console.log(err)
      }
}

