// Get cookies details

export const getCookie = (name) => {
      try {
            const cookies = document.cookie.split("; ");
            const cookie = cookies.find((row) => row.startsWith(name + "="));
            return cookie ? cookie.split("=")[1] : null;
      } catch (err) {
            console.log(err);
            return null;
      }
};

export const storeWorktulaCookiesData = async () => {
      try {
            const cookies = document.cookie.split("; ");
            const cookie = cookies.find((row) => row.startsWith('CK_Cons' + "="));
            const resultCookie = cookie ? cookie.split("=")[1] : null;
            if (resultCookie) {
                  const worktualData = document.cookie.split("; ");
                  const cookie = worktualData.find((row) => row.startsWith('US_TKG' + "="));
                  return cookie ? cookie.split("=")[1] : null;
            }
            return null
      } catch (err) {
            console.log(err);
      }
};

export const setItemWithExpiry = (key, value, ttl) => {
      const now = new Date();
      const item = {
            value,
            expiry: now.getTime() + ttl,
      };
      localStorage.setItem(key, JSON.stringify(item));
};


export const getItemWithExpiry = (key) => {
      const itemStr = localStorage.getItem(key);
      if (!itemStr) return null;
      const item = JSON.parse(itemStr);
      const now = new Date();
      if (now.getTime() > item.expiry) {
            localStorage.removeItem(key);
            return null;
      }
      return item.value;
};


