export const getClientAddress = async (dispatch) => {
      try {
            await fetch(`https://ipinfo.io/json`)
                  .then(async (e) => {
                        const res = await e.json()
                        const { city, region, ip } = res;
                        const country = findCountry(res?.country);
                        const address_data = [city, region, country].filter(Boolean)?.join(', ')?.trim();
                        if(res){
                              dispatch(messageActions.storeClientLocationDetails(res))
                        }
                        if(!address_data?.includes("undefined")){
                              dispatch(messageActions.storeClientLocation(address_data))
                        }
                        if(ip){
                              dispatch(messageActions.storeIpAddress(ip));
                        }else {
                              getWorktualIpAddress()
                        }
                  })
                  .catch((error) => {
                        getWorktualIpAddress(dispatch)
                        console.log(error);
                  });
      } catch (error) {
            console.log(error)
      }
}

export const getWorktualIpAddress =(dispatch)=> {
      try {
            fetch('https://getip.worktual.co.uk/')
                  .then((res) => {
                        if (!res.ok) {
                              throw new Error('Network response was not ok');
                        }
                        return res.json();
                  })
                  .then((ipData) => {
                        dispatch(messageActions.storeIpAddress(ipData.clientIPv6));
                  })
                  .catch((error) => {
                        console.log(error);
                  });
      } catch (error) {
            console.log(error)
      }
}

